import { afterEach, describe, expect, it } from "vitest";
import { cleanup, fireEvent, render, screen, within } from "@testing-library/react";
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import IndividualPanel from "./IndividualPanel";
import MarkerSummaryMenu from "./MarkerSummaryMenu";
import { buildTooltip } from "./PedigreeCanvas";
import type { IndividualDetail } from "../hooks/useApi";

// API replies for the simulated FlexQTL/Binko fixtures and Example.dat,
// generated by backend/tests/test_frontend_fixture.py.
const panels = JSON.parse(readFileSync(resolve("src/test/fixtures/panels.json"), "utf-8"));

afterEach(cleanup);

function show(file: string, id: string) {
  const { pedigree, details } = panels[file];
  render(<IndividualPanel individual={details[id] as IndividualDetail} traits={pedigree.traits}
    parentLabels={pedigree.parent_labels} markerSummary={pedigree.marker_summary}
    onSelectId={() => {}} onClose={() => {}} />);
}

// The parentage row of a label (the genotype table's headers repeat it).
const parentRow = (label: string) => screen.getAllByText(label)[0].closest("div")!.textContent;

const markerRow = (marker: string) =>
  screen.getByRole("table", { name: "Genotypes" }).querySelector(`tr[data-marker="${marker}"]`) as HTMLElement;

describe("parent labels follow the caption", () => {
  it("PARENT1/PARENT2: Parent 1 and Parent 2", () => {
    show("binko_legacy", "G1_001");
    expect(parentRow("Parent 1")).toBe("Parent 1F005");
    expect(parentRow("Parent 2")).toBe("Parent 2F002");
  });

  it("FEMALE/MALE: Female parent and Male parent", () => {
    show("example", "Elstar");
    expect(parentRow("Female parent")).toBe("Female parentGoldenD");
    expect(parentRow("Male parent")).toBe("Male parentIngridM");
  });

  it("in the chart's tooltip too", () => {
    const tip = buildTooltip({ id: "X", label: "X", x: 0, y: 0, generation: 1, cross_type: "cross",
      female_parent: "P", male_parent: null }, panels.flexqtl.pedigree.parent_labels);
    expect([...tip.querySelectorAll("div")].map(d => d.textContent)).toEqual(
      ["Parent 1: P", "Parent 2: -", "Generation: 1"]);
  });
});

describe("Markers section", () => {
  it("lists each linkage group's loci, the two alleles in file order and the code", () => {
    show("binko_legacy", "G1_001");
    const table = screen.getByRole("table", { name: "Genotypes" });
    expect([...table.querySelectorAll("thead th")].map(t => t.textContent))
      .toEqual(["Locus", "Parent 1", "Parent 2", "Code"]);
    expect(screen.getAllByRole("rowgroup", { name: /^Linkage group/ }).map(g => g.getAttribute("aria-label")))
      .toEqual(["Linkage group 1", "Linkage group 2", "Linkage group 3"]);
    const row = markerRow("M1_001");                                 // "G 1  A 1"
    expect([...row.querySelectorAll("td")].map(td => td.textContent)).toEqual(["M1_001", "G", "A", "1"]);
    expect(within(row).getByText("1").getAttribute("title"))
      .toMatch(/^Code 1 \(MA\): Missing in the data and filled in/);
  });

  it("shows unknown alleles and codes without a FlexQTL meaning", () => {
    show("binko_legacy", "F003");
    const row = markerRow("M1_001");                                 // "- 5  - 5"
    expect([...row.querySelectorAll("td")].map(td => td.textContent)).toEqual(["M1_001", "–", "–", "5"]);
  });

  it("says when an individual has no genotype rows", () => {
    show("binko_legacy", "DUMMY_G1_007_F");
    expect(within(screen.getByRole("region", { name: "Markers" })).getByText("No genotype data")).toBeTruthy();
  });

  it("Example.dat (no FACTOR0): codes are color codes, without FlexQTL's meanings", () => {
    show("example", "Elstar");
    const badges = [...screen.getByRole("table", { name: "Genotypes" }).querySelectorAll("[data-code]")];
    expect(badges.length).toBeGreaterThan(0);
    for (const b of badges) expect(b.getAttribute("title")).toBe(`Color code ${b.textContent}`);
    expect(document.body.textContent).not.toMatch(/FlexQTL|\(MA\)|\(OEA\)/);
  });

  it("Example.dat: female and male parent columns, the null symbol as written", () => {
    show("example", "Elstar");
    expect([...screen.getByRole("table", { name: "Genotypes" }).querySelectorAll("thead th")]
      .map(t => t.textContent)).toEqual(["Locus", "Female parent", "Male parent", "Code"]);
    expect([...markerRow("SSR1").querySelectorAll("td")].map(td => td.textContent))
      .toEqual(["SSR1", "180", "$", "2"]);
  });
});

describe("IBD section", () => {
  const homologue = (n: 1 | 2) =>
    screen.getByRole("generic", { name: `Homologue from Parent ${n}` }).textContent;

  it("shows each homologue's most probable founder allele, founder and probability", () => {
    show("flexqtl", "G1_001");
    expect((screen.getByLabelText("IBD linkage group") as HTMLSelectElement).value).toBe("1");
    expect((screen.getByLabelText("IBD position") as HTMLSelectElement).value).toBe("0.000");
    expect(homologue(1)).toBe("Homologue from parent 10.95F003 · founder allele 23");   // 0.05 hidden
    expect(homologue(2)).toBe("Homologue from parent 21.00F010 · founder allele 38");
  });

  it("adds the next most probable founder allele when above 0.10", () => {
    show("flexqtl", "G1_007");
    expect(homologue(1)).toBe("Homologue from parent 1" +
      "0.50DUMMY_G1_007_M · founder allele 10.50DUMMY_G1_007_M · founder allele 2");
  });

  it("keeps each FlexQTL linkage group's own positions (#18)", () => {
    show("flexqtl", "G1_001");
    const positions = () => [...(screen.getByLabelText("IBD position") as HTMLSelectElement).options]
      .map(o => o.value);
    const inGroup1 = positions();
    const atZero1 = homologue(1);
    fireEvent.change(screen.getByLabelText("IBD linkage group"), { target: { value: "2" } });
    const inGroup2 = positions();
    expect(inGroup1).toHaveLength(21);
    expect(inGroup2).toHaveLength(21);
    expect(inGroup2[0]).toBe("0.000");
    expect((screen.getByLabelText("IBD position") as HTMLSelectElement).value).toBe("0.000");
    expect(homologue(1)).not.toBe(atZero1);                       // group 2's own values
    fireEvent.change(screen.getByLabelText("IBD position"), { target: { value: "100.000" } });
    expect(homologue(1)).toMatch(/^Homologue from parent 1\d\.\d\d/);
  });

  it("names the supplied row of a Binko dummy founder", () => {
    show("binko_ibd", "DUMMY_G1_007_F");
    expect(homologue(1)).toBe("Homologue from parent 11.00DUMMY_G1_007_F · founder allele 13");
  });
});

describe("marker data summary", () => {
  it("lists loci and IBD positions per linkage group and the codes in use", () => {
    render(<MarkerSummaryMenu summary={panels.flexqtl.pedigree.marker_summary} />);
    fireEvent.click(screen.getByRole("button", { name: /Marker data/ }));
    const dialog = screen.getByRole("dialog", { name: "Marker data" });
    expect(within(dialog).getByText("42 loci on 2 linkage groups")).toBeTruthy();
    expect([...dialog.querySelectorAll("tbody tr")].map(r => r.textContent)).toEqual(["12121", "22121"]);
    expect(dialog.textContent).toContain("3,108 genotype rows for 74 individuals; 42 IBD positions over 58 founder alleles");
    const codes = [...dialog.querySelectorAll("[data-code]")].map(b => b.parentElement!.textContent);
    expect(codes).toEqual(["0OC2,717", "5IM378", "11OPhE13"]);
  });

  it("Example.dat: codes in use without FlexQTL's names", () => {
    render(<MarkerSummaryMenu summary={panels.example.pedigree.marker_summary} />);
    fireEvent.click(screen.getByRole("button", { name: /Marker data/ }));
    const dialog = screen.getByRole("dialog", { name: "Marker data" });
    const codes = [...dialog.querySelectorAll("[data-code]")];
    expect(codes.map(b => b.parentElement!.textContent)).toEqual(
      ["0color code32", "1color code1", "2color code7"]);
    expect(codes.map(b => b.getAttribute("title"))).toEqual(
      ["Color code 0", "Color code 1", "Color code 2"]);
  });
});
